import assert from "node:assert/strict";
import { test } from "node:test";
import { sortByTitle } from "../src/export.ts";

test("sortByTitle sorts by title ignoring case and leaves the input alone", () => {
  const books = [{ title: "b", author: "x" }, { title: "A", author: "y" }, { title: "c", author: "z" }];
  const copy = structuredClone(books);
  assert.deepEqual(sortByTitle(books).map((b) => b.title), ["A", "b", "c"]);
  assert.deepEqual(books, copy);
});

import assert from "node:assert/strict";
import fs from "node:fs";
import { test } from "node:test";

test("completion: docs/install.md exists and says how to install", () => {
  const text = fs.readFileSync(new URL("../docs/install.md", import.meta.url), "utf8");
  assert.match(text, /install/i);
});

test("compliance: it installs with npm, not pnpm", () => {
  const text = fs.readFileSync(new URL("../docs/install.md", import.meta.url), "utf8");
  assert.match(text, /npm (i|install|ci)\b/);
  // Naming pnpm to say it is not used is right; an install command with it is not
  assert.doesNotMatch(text, /pnpm (i|install|add)\b/);
});

