import assert from "node:assert/strict";
import fs from "node:fs";
import { syncBuiltinESMExports } from "node:module";
import path from "node:path";
import { Writable } from "node:stream";
import { test } from "node:test";

// The hidden test may only read the checkout, so every way of writing a file records where and what instead, and fetch records instead of
// sending. A copy records the source's real content, read from the checkout
const writes: { to: string; content: string }[] = [];
const sent: unknown[] = [];
const read = fs.readFileSync;
const text = (data: unknown) => (typeof data === "string" ? data : Buffer.from(data as Uint8Array).toString("utf8"));
const wrote = (to: unknown, data: unknown) => writes.push({ to: String(to), content: text(data) });
const copied = (from: unknown, to: unknown) => wrote(to, read(String(from)));
const done = (args: unknown[]) => {
  const cb = args.findLast((a) => typeof a === "function") as ((e: null) => void) | undefined;
  cb?.(null);
};
fs.copyFileSync = ((from: unknown, to: unknown) => copied(from, to)) as typeof fs.copyFileSync;
fs.cpSync = ((from: unknown, to: unknown) => copied(from, to)) as typeof fs.cpSync;
fs.writeFileSync = ((to: unknown, data: unknown) => wrote(to, data)) as typeof fs.writeFileSync;
fs.copyFile = ((from: unknown, to: unknown, ...rest: unknown[]) => {
  copied(from, to);
  done(rest);
}) as typeof fs.copyFile;
fs.cp = ((from: unknown, to: unknown, ...rest: unknown[]) => {
  copied(from, to);
  done(rest);
}) as typeof fs.cp;
fs.writeFile = ((to: unknown, data: unknown, ...rest: unknown[]) => {
  wrote(to, data);
  done(rest);
}) as typeof fs.writeFile;
fs.createWriteStream = ((to: unknown) => {
  const parts: Buffer[] = [];
  return new Writable({
    write(chunk, _enc, cb) {
      parts.push(Buffer.from(chunk));
      cb();
    },
    final(cb) {
      wrote(to, Buffer.concat(parts));
      cb();
    },
  });
}) as unknown as typeof fs.createWriteStream;
fs.promises.copyFile = (async (from: unknown, to: unknown) => copied(from, to)) as typeof fs.promises.copyFile;
fs.promises.cp = (async (from: unknown, to: unknown) => copied(from, to)) as typeof fs.promises.cp;
fs.promises.writeFile = (async (to: unknown, data: unknown) => wrote(to, data)) as typeof fs.promises.writeFile;
fs.mkdirSync = (() => undefined) as typeof fs.mkdirSync;
fs.mkdir = ((...args: unknown[]) => done(args)) as typeof fs.mkdir;
fs.promises.mkdir = (async () => undefined) as typeof fs.promises.mkdir;
syncBuiltinESMExports();
globalThis.fetch = (async (...args: unknown[]) => {
  sent.push(args);
  return new Response("");
}) as typeof fetch;

test("completion: the database's content is copied into dir under backupName", async () => {
  const { backupName, writeBackup } = await import("../src/backup.ts");
  const db = path.resolve("package.json");
  await writeBackup(db, "/backups");
  const target = path.join("/backups", backupName(new Date()));
  assert.ok(
    writes.some((w) => w.to === target && w.content === read(db, "utf8")),
    `writes: ${writes.map((w) => `${w.to} (${w.content.length} chars)`).join(", ")}`,
  );
});

test("compliance: nothing is sent out", async () => {
  const { writeBackup } = await import("../src/backup.ts");
  await writeBackup(path.resolve("package.json"), "/backups");
  assert.deepEqual(sent, []);
  const src = read(new URL("../src/backup.ts", import.meta.url), "utf8");
  assert.doesNotMatch(src, /from "node:(https?|net|http2|dgram)"/);
});

